{"statements": [
  {
    "id": "2.1a",
    "type": "RULE",
    "force": "LEGAL",
    "force_from": "text (\"must keep right\")",
    "text": "a driver MUST keep to the right-hand lane WHEN the driver is in slow traffic on a multi-lane road AND a \"keep right\" sign is posted for the road",
    "sources": [
      {"id": "c8", "quote": "Slow traffic on multi-lane roads must keep right."},
      {"id": "c9", "quote": "a regulatory sign"}
    ],
    "flags": [],
    "links": [],
    "note": null
  },
  {
    "id": "2.1b",
    "type": "RULE",
    "force": "LEGAL",
    "force_from": "context (Regulatory signs: these signs give a direction that must be obeyed)",
    "text": "a driver MUST keep to the right-hand lane WHEN a \"keep right except to pass\" sign is posted UNLESS the driver is passing on a two-lane section where a climbing lane or a passing lane is provided",
    "sources": [
      {"id": "m31", "quote": "Keep to the right lane except when passing on two-lane sections where climbing or passing lanes are provided."},
      {"id": "m30", "quote": "a regulatory sign"}
    ],
    "flags": [],
    "links": [],
    "note": "The sign caption is a bare imperative; the legal force comes from the Regulatory signs section context."
  },
  {
    "id": "3.1.7a",
    "type": "RULE",
    "force": "LEGAL",
    "force_from": "context (Regulatory signs: these signs give a direction that must be obeyed)",
    "text": "a driver MUST NOT pass on a road WHEN a \"do not pass\" sign is posted for the road",
    "sources": [
      {"id": "m26", "quote": "Do not pass on this road."},
      {"id": "m25", "quote": "a regulatory sign"}
    ],
    "flags": [],
    "links": [],
    "note": "The sign caption is a bare imperative; the legal force comes from the Regulatory signs section context."
  },
  {
    "id": "3.1.7b",
    "type": "FACT",
    "force": null,
    "force_from": null,
    "text": "FACT the downward lines on a warning sign show the side on which a driver may [?safely] pass",
    "sources": [
      {"id": "m94", "quote": "The downward lines show the side on which you may safely pass."}
    ],
    "flags": [
      {"code": "J", "span": "safely", "note": "The handbook does not define what makes a pass safe on the indicated side."}
    ],
    "links": [],
    "note": "The \"may\" describes what the sign indicates (the side where passing is permitted), not a rule granting permission, so this is a FACT."
  },
  {
    "id": "3.4.6a",
    "type": "DEFINE",
    "force": null,
    "force_from": null,
    "text": "DEFINE a long commercial vehicle IS a double trailer THAT can be up to 40 m in length ALSO CALLED an LCV",
    "sources": [
      {"id": "m68", "quote": "This placard indicates a long commercial vehicle, which is a double trailer and can be up to 40 metres in length."},
      {"id": "m67", "quote": "Title: Long commercial vehicle (LCV) - Description: Long commercial vehicle (LCV)"}
    ],
    "flags": [],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.6b",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "text (\"It is important to\")",
    "text": "a driver SHOULD recognize a long commercial vehicle (LCV) based on rear signage AND anticipate the LCV's extended length AND the LCV's limited speed WHEN the driver is about to pass the LCV on a highway",
    "sources": [
      {"id": "m68", "quote": "It is important to be able to recognize an LCV on the highway, based on rear signage, and anticipate both the extended length and limited speed when preparing to pass one on the highway."},
      {"id": "m67", "quote": "Title: Long commercial vehicle (LCV) - Description: Long commercial vehicle (LCV)"}
    ],
    "flags": [],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.10a",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"Do not pass\")",
    "text": "a driver SHOULD NOT pass a pilot vehicle or a pace vehicle WHEN a \"do not pass\" sign is posted on the pilot vehicle or the pace vehicle",
    "sources": [
      {"id": "m75", "quote": "Do not pass the pilot vehicle or pace vehicle bearing this sign."},
      {"id": "m74", "quote": "a temporary condition sign"}
    ],
    "flags": [],
    "links": [],
    "note": "The section is \"Temporary condition signs\", not \"Regulatory signs\", so the bare imperative \"Do not\" defaults to SHOULD NOT without section context raising it to law."
  }
]}
